// Simple Asteroid Dodge game
// Canvas element with id="game" must exist in the HTML.
(function () {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  const ship = {
    x: width / 2,
    y: height - 30,
    size: 20,
    speed: 5,
  };

  let asteroids = [];
  let stars = [];
  let score = 0;
  let gameOver = false;
  let spawnTimer = 0;
  let starTimer = 0;
  let speedFactor = 1;

  // Input handling (keyboard & mouse)
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    ship.x = e.clientX - rect.left;
    ship.y = e.clientY - rect.top;
  });

  function spawnAsteroid() {
    const size = Math.random() * 30 + 10;
    asteroids.push({
      x: Math.random() * (width - size),
      y: -size,
      size,
      speed: (Math.random() * 1 + 0.5) * speedFactor,
    });
  }

  function spawnStar() {
    const size = 5;
    stars.push({
      x: Math.random() * (width - size),
      y: -size,
      size,
      speed: 2 * speedFactor,
    });
  }

  function update(dt) {
    if (gameOver) return;
    // Move ship with arrow keys if mouse not used
    if (keys['ArrowLeft']) ship.x -= ship.speed;
    if (keys['ArrowRight']) ship.x += ship.speed;
    if (keys['ArrowUp']) ship.y -= ship.speed;
    if (keys['ArrowDown']) ship.y += ship.speed;
    // Keep ship within bounds
    ship.x = Math.max(0, Math.min(width, ship.x));
    ship.y = Math.max(0, Math.min(height, ship.y));

    spawnTimer += dt;
    if (spawnTimer > 800) { // ms
      spawnAsteroid();
      spawnTimer = 0;
    }
    starTimer += dt;
    if (starTimer > 1500) {
      spawnStar();
      starTimer = 0;
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // collision with ship (circle vs triangle approximated as circle)
      const dx = a.x + a.size / 2 - ship.x;
      const dy = a.y + a.size / 2 - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.size / 2 + ship.size / 2) {
        gameOver = true;
      }
      if (a.y > height) {
        asteroids.splice(i, 1);
        score++;
        // gradually increase difficulty
        if (score % 10 === 0) speedFactor += 0.1;
      }
    }
    // Update stars (collect for points)
    for (let i = stars.length - 1; i >= 0; i--) {
      const s = stars[i];
      s.y += s.speed;
      const dx = s.x + s.size / 2 - ship.x;
      const dy = s.y + s.size / 2 - ship.y;
      if (Math.hypot(dx, dy) < s.size / 2 + ship.size / 2) {
        score += 5;
        stars.splice(i, 1);
        continue;
      }
      if (s.y > height) stars.splice(i, 1);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Ship (triangle)
    ctx.fillStyle = 'cyan';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y - ship.size / 2);
    ctx.lineTo(ship.x - ship.size / 2, ship.y + ship.size / 2);
    ctx.lineTo(ship.x + ship.size / 2, ship.y + ship.size / 2);
    ctx.closePath();
    ctx.fill();
    // Asteroids
    ctx.fillStyle = 'gray';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    // Stars
    ctx.fillStyle = 'yellow';
    stars.forEach(s => {
      ctx.beginPath();
      ctx.arc(s.x + s.size / 2, s.y + s.size / 2, s.size / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    // Score
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
